-- ============================================================
-- league_data_epl.sql — 英超真实数据入库（由 scripts_cloudbase/build-epl-db.py 生成）
-- 数据源：赛程=腾讯体育（data/epl.json）｜积分榜/射手榜=央视体育；赛程比分页=腾讯体育
-- 前置：db/schema.sql（season / zone 列）
-- 执行顺序：schema.sql → league_data.sql → league_data_nba.sql → league_data_cba.sql
--   → 本文件 → league_data_ucl.sql
--   （league_data.sql 里有一段 epl 的旧数据，须被本文件覆盖）
-- 可重复执行：先清空 league_id=epl / league=英超 的行，再插入
-- 规模：league_schedule 760 · league_standings 40 · league_players 100 · league_brackets 1 · matches 3
-- ============================================================

BEGIN;

-- ---------- 1. 联赛维度表（与真实数据的 desc / tabs 对齐）----------
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sport = EXCLUDED.sport,
  emoji = EXCLUDED.emoji, description = EXCLUDED.description,
  tabs = EXCLUDED.tabs, updated_at = EXCLUDED.updated_at;

-- ---------- 2. 清空英超旧数据（含 league_data.sql 灌的 epl 段）----------
DELETE FROM public.league_schedule WHERE league_id = 'epl';
DELETE FROM public.league_standings WHERE league_id = 'epl';
DELETE FROM public.league_players WHERE league_id = 'epl';
DELETE FROM public.league_brackets WHERE league_id = 'epl';
DELETE FROM public.matches WHERE league = '英超';

-- ---------- 3. league_schedule（两个赛季 760 场）----------

-- ---------- 4. league_standings（两个赛季各 20 队，无分区）----------

-- ---------- 5. league_players（26-27 射手榜 100 人，board=scorers）----------

-- ---------- 6. league_brackets（26-27 争冠形势 kind=race）----------

-- ---------- 7. matches（赛程比分页英超段 3 条）----------

COMMIT;

-- 收尾自检
SELECT 'league_schedule' t, count(*) FROM public.league_schedule WHERE league_id='epl'
UNION ALL SELECT 'league_standings', count(*) FROM public.league_standings WHERE league_id='epl'
UNION ALL SELECT 'league_players',   count(*) FROM public.league_players   WHERE league_id='epl'
UNION ALL SELECT 'league_brackets',  count(*) FROM public.league_brackets  WHERE league_id='epl'
UNION ALL SELECT 'matches(英超)',    count(*) FROM public.matches        WHERE league='英超';
SELECT season, count(*) FROM public.league_schedule WHERE league_id='epl' GROUP BY season ORDER BY season;
SELECT season, count(*) FROM public.league_standings WHERE league_id='epl' GROUP BY season ORDER BY season;
